// Market-drops study, pages: bears, ai-dotcom, scenarios, drills, glossary, method, sources, index.
const fs = require("fs"), path = require("path");
const L = require("./lib.js"), G = require("./sitegen.js"), K = require("./kit.js");
const { pct, mag, num, tbl, P, PB, tiles, take, warn, ul, link, esc } = G, { median, mean, quantile, nice, niceM, niceS } = L;

/** very small Markdown → HTML for the research notes (headings, tables, lists, bold, links, paragraphs) */
function md(text) {
  const inl = s => esc(s).replace(/\*\*([^*]+)\*\*/g, "<b>$1</b>").replace(/`([^`]+)`/g, "<code>$1</code>").replace(/\[([^\]]+)\]\((https?:[^)\s]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>').replace(/(^|[\s(])(https?:\/\/[^\s<)]+)/g, (m, a, u) => `${a}<a href="${u}" target="_blank" rel="noopener">${u.replace(/^https?:\/\/(www\.)?/, "").slice(0, 60)}</a>`);
  const out = [], Ls = text.replace(/\r/g, "").split("\n"); let i = 0;
  while (i < Ls.length) { const l = Ls[i];
    if (/^\s*$/.test(l)) { i++; continue; }
    const h = /^(#{1,5})\s+(.*)$/.exec(l); if (h) { const lv = Math.min(5, h[1].length + 2); out.push(`<h${lv}>${inl(h[2])}</h${lv}>`); i++; continue; }
    if (/^\s*\|/.test(l)) { const rows = []; while (i < Ls.length && /^\s*\|/.test(Ls[i])) { rows.push(Ls[i].trim().replace(/^\||\|$/g, "").split("|").map(c => c.trim())); i++; } const body = rows.filter(r => !r.every(c => /^:?-{2,}:?$/.test(c)));
      out.push(`<div class="scroll"><table class="t small wrap"><thead><tr>${body[0].map(c => `<th>${inl(c)}</th>`).join("")}</tr></thead><tbody>${body.slice(1).map(r => `<tr>${r.map(c => `<td>${inl(c)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`); continue; }
    if (/^\s*([-*]|\d+\.)\s+/.test(l)) { const ord = /^\s*\d+\./.test(l), items = []; while (i < Ls.length && (/^\s*([-*]|\d+\.)\s+/.test(Ls[i]) || (/^\s{2,}\S/.test(Ls[i]) && items.length))) { if (/^\s*([-*]|\d+\.)\s+/.test(Ls[i])) items.push(Ls[i].replace(/^\s*([-*]|\d+\.)\s+/, "")); else items[items.length - 1] += " " + Ls[i].trim(); i++; } out.push(`<${ord ? "ol" : "ul"}>${items.map(x => `<li>${inl(x)}</li>`).join("")}</${ord ? "ol" : "ul"}>`); continue; }
    const para = []; while (i < Ls.length && !/^\s*$/.test(Ls[i]) && !/^(#{1,5})\s/.test(Ls[i]) && !/^\s*\|/.test(Ls[i]) && !/^\s*([-*]|\d+\.)\s+/.test(Ls[i])) { para.push(Ls[i].trim()); i++; } out.push(`<p>${inl(para.join(" "))}</p>`); }
  return out.join("\n");
}

module.exports = function (site, C, M) {
  const E = C.spx, cur = E[E.length - 1], ep = id => E.find(e => e.id === id), label = e => e.name || niceM(e.peak), SPX = K.SPX, done = E.filter(e => !e.open);
  const e00 = ep("2000"), e07 = ep("2007"), e18 = ep("2018b"), e22 = ep("2022"), N = cur.daysToLow;
  const stockPx = (sym, from, to) => { const B = L.anyBars(sym); return B ? B.filter(b => b.d >= from && b.d <= to) : []; };

  // =============================================================== BEARS
  {
    const p = site.page("bears"), q00 = C.ndq.find(e => e.peak.startsWith("2000")), q07 = C.ndq.find(e => e.peak.startsWith("2007"));
    p.lede = `The S&amp;P 500 fell ${mag(e00.depth, 0)} over ${e00.daysToLow} sessions from March 2000 and ${pct(e07.depth, 0)} over ${e07.daysToLow} sessions from October 2007. Neither looked like a bear market in its first two months. This page sets out how each unfolded, how many rallies failed on the way, and what the first weeks looked like at the time.`;
    p.h(tiles([[pct(e00.depth, 0), "S&amp;P 500, 24 Mar 2000 → 9 Oct 2002", "neg"], [pct(q00.depth, 0), "Nasdaq Composite, 10 Mar 2000 → 9 Oct 2002", "neg"], [String(e00.nFailed), "rallies of 5%+ in the S&amp;P that failed (2000–02)"], [pct(e07.depth, 0), "S&amp;P 500, 9 Oct 2007 → 9 Mar 2009", "neg"], [String(e07.nFailed), "rallies of 5%+ that failed (2007–09)"], [String(q00.nFailed), "failed rallies of 5%+ in the Nasdaq, 2000–02"]]));
    const first = (e) => { const i = L.bi(SPX, e.peak); return [33, 65, 130, 260].map(k => (SPX[Math.min(SPX.length - 1, i + k)].c / SPX[i].c - 1) * 100); };
    p.sec("first", "What the first weeks looked like", `The present drop is ${N} sessions old. The same point in the two bears, and in two drops that ended as corrections or a milder bear:`);
    p.h(tbl(["Drop", { t: `After ${N} sessions`, num: true }, { t: "After 65 (3 months)", num: true }, { t: "After 130 (6 months)", num: true }, { t: "After 260 (1 year)", num: true }, { t: "Final", num: true }], [["2026 (now)", P(cur.depth), "—", "—", "—", "—"], ...[e18, e00, e07, e22].map(e => { const f = first(e); return [label(e), P(f[0]), P(f[1]), P(f[2]), P(f[3]), P(e.depth)]; })], { note: `Per cent from the closing high, S&amp;P 500. After ${N} sessions the 2000 and 2007 bears were shallower than the present drop. The 2000 bear was back within 1% of its high five months later (1 September 2000); the 2007 bear recovered to within 9% of its high seven months in (19 May 2008). The main declines came after that.` }));
    p.fig({ type: "lines", xt: "n", yf: "pct", xl: "sessions after the peak", xn: "session", h: 440, hl: [{ y: -10, t: "−10%" }, { y: -20, t: "−20%" }], vl: [{ x: N, t: "today" }], series: [{ t: "2026 (now)", s: "now", d: K.pathFromPeak(SPX, cur.peak, N), c: "#111", w: 3 }, { t: "2000–02", s: "2000", d: K.pathFromPeak(SPX, e00.peak, 700), ci: 7, w: 2 }, { t: "2007–09", s: "2007", d: K.pathFromPeak(SPX, e07.peak, 420), ci: 6, w: 2 }, { t: "2018", s: "2018", d: K.pathFromPeak(SPX, e18.peak, 150), ci: 0, w: 2 }, { t: "2022", s: "2022", d: K.pathFromPeak(SPX, e22.peak, 370), ci: 1, w: 2 }] },
      { title: "The two bears, 2018 and 2022, from their peaks, with the present", cap: "S&amp;P 500, per cent from the closing high.", note: "The 2000–02 line spent its first five months between −1% and −12%, was within 1% of the high on 1 September 2000, and only then broke down. The 2007–09 line was back within 9% of its high seven months in (19 May 2008)." });
    p.frag("bears-first-months");
    for (const [e, q, evName, title] of [[e00, q00, "2000", "2000–02: the dot-com bust"], [e07, q07, "2007", "2007–09: the financial crisis"]]) {
      const evs = K.events(evName), from = K.tradeDay(e.peak, -160), to = K.tradeDay(e.low, 200), blk = K.evBlock(evs, from, to);
      p.sec("b" + evName, title, `S&amp;P 500 ${pct(e.depth)} in ${e.daysToLow} sessions (${(e.daysToLow / 252).toFixed(1)} years); ${e.nFailed} rallies of 5% or more failed before the low held.`);
      p.fig(K.epSpec(site, "^GSPC", e, { tf: "W", from, to, h: 440, log: true, marks: blk.marks }), { title: `S&P 500, weekly, ${from.slice(0, 4)}–${to.slice(0, 4)}`, cap: "Amber bands: rallies of 5%+ that failed. Green: the rally from the final low. Lines: 10- and 40-week averages.", after: blk.list, minH: 560 });
      p.fig(K.epSpec(site, "^IXIC", q, { tf: "W", from, to, h: 380, log: true, spxMarks: true, tag: evName + "q" }), { title: "Nasdaq Composite, weekly, same period", cap: `${pct(q.depth, 0)} peak to low; ${q.nFailed} failed rallies of 5%+.`, minH: 480 });
      const fr = e.rallies.filter(r => r.cls === "failed");
      p.h(`<details><summary>Every rally of 5% or more that failed (${fr.length})</summary>${tbl(["From the low of", { t: "Index below its high then", num: true }, { t: "Rally", num: true }, { t: "Sessions to its top", num: true }, { t: "Sessions until the low broke", num: true }, "Follow-through day", "Above 50-day", "Above 200-day"], fr.map(r => [nice(r.low), P(r.depthAtLow, 0), P(r.gain, 0), r.days, r.daysToCut, r.f.ftd ? "session " + r.f.ftd : "none", r.f.r50ok ? "yes" : "no", r.f.r200ok ? "yes" : "no"]), { cls: "small" })}</details>`);
      p.frag(evName === "2000" ? "bears-2000-story" : "bears-2007-story");
    }
    p.frag("bears-rallies");
    p.frag("bears-fed-credit");
    p.frag("bears-lows");
    p.frag("bears-sectors-leaders");
    p.h(`<p>Sector and stock tables for both bears are on ${link("sectors", "Sectors and themes", "d2000")} and ${link("leaders", "The stocks that led", "other")}; the signs at their lows are on ${link("bottoms")}.</p>`);
    p.h(take([`Neither bear announced itself. After ${N} sessions both were shallower than the present drop, and both later rallied (2000 to within 1% of its high, 2007 to within 9%) before the real decline.`, `What distinguished them was not the first leg but persistence: ${e00.nFailed} and ${e07.nFailed} failed rallies, a 200-day average that turned down and stayed down, earnings that fell by more than half, and (in 2007–09) credit spreads that kept widening.`,
      `In both, the Fed was cutting rates for most of the way down. Rate cuts did not end them.`, `Their final lows were lows of exhaustion: VIX and new-low counts had peaked months earlier.`], "What to take from it"));
    p.h(warn(`Two episodes, both with recessions and both with a broken financing channel (telecom and dot-com equity in 2000; mortgages and banks in 2007). They show what a bear can look like, not what one must look like. The 1973–74 and 2022 bears had other mechanics (inflation and rates).`));
  }

  // =============================================================== AI vs DOT-COM
  {
    const p = site.page("ai-dotcom");
    p.lede = "The case that today is unlike 2000 rests on profits: the companies leading the AI build-out earn very large sums, where the dot-coms of 1999 earned nothing. This page tests that case against what happened to the profitable leaders of 2000, and sets the research on AI spending and its financing beside it.";
    p.sec("giants", "The profitable giants of 2000", "The largest technology companies of March 2000 were not pets.com. They were highly profitable, dominant in their markets and growing. This is what their shares did.");
    const giants = ["CSCO", "MSFT", "INTC", "ORCL", "QCOM", "TXN", "IBM", "AMAT", "EBAY", "AMZN", "ADBE", "NVDA"], nameOf = s => (L.universe().stocks[s] || {}).name || s;
    const gstat = sym => { const B = L.anyBars(sym), a = L.bia(B, "1999-10-01"), z = L.bi(B, "2000-12-29"); let pk = a; for (let i = a; i <= z; i++) if (B[i].c > B[pk].c) pk = i; let lo = pk; const zz = L.bi(B, "2003-12-31"); for (let i = pk; i <= zz; i++) if (B[i].c < B[lo].c) lo = i; let back = null; for (let i = lo; i < B.length; i++) if (B[i].c >= B[pk].c) { back = i; break; } return { fall: (B[lo].c / B[pk].c - 1) * 100, years: back ? L.daysBetween(B[pk].d, B[back].d) / 365.25 : null, backYear: back ? B[back].d.slice(0, 4) : null }; };
    const gs = sym => { const g = gstat(sym); return `${nameOf(sym).replace(/ Systems| Corporation|,? Inc\.?/g, "")}'s shares fell ${mag(-g.fall, 0).replace("+", "")} and ${g.years ? `first closed above their 2000 high again in ${g.backYear}, ${Math.round(g.years)} years later` : "have not closed above their 2000 high since"}.`; };
    const rowG = sym => { const B = L.anyBars(sym); if (!B) return null; const a = L.bia(B, "1999-10-01"), z = L.bi(B, "2000-12-29"); let pk = a; for (let i = a; i <= z; i++) if (B[i].c > B[pk].c) pk = i; let lo = pk; const zz = L.bi(B, "2003-12-31"); for (let i = pk; i <= zz; i++) if (B[i].c < B[lo].c) lo = i; let back = null; for (let i = lo; i < B.length; i++) if (B[i].c >= B[pk].c) { back = i; break; }
      const at = (iso) => { const k = L.bi(B, iso); return (B[k].c / B[pk].c - 1) * 100; };
      return [`<b>${sym}</b> <span class="dim">${nameOf(sym)}</span>`, nice(B[pk].d), nice(B[lo].d), PB((B[lo].c / B[pk].c - 1) * 100, 100, 0), P(at(L.addDays(B[pk].d, 365 * 5)), 0), P(at(L.addDays(B[pk].d, 365 * 10)), 0), back ? `${nice(B[back].d).slice(-4)} (${((L.daysBetween(B[pk].d, B[back].d)) / 365.25).toFixed(0)} years)` : "not yet"]; };
    p.h(tbl(["Company", "2000 high", "Low by end-2003", { t: "Fall", num: true }, { t: "5 years after the high", num: true }, { t: "10 years after", num: true }, "Back above the 2000 high"], giants.map(rowG).filter(Boolean), { note: "Split-adjusted closing prices, dividends not included. Every company here except Amazon was profitable in 2000, and most kept growing revenue and profit through the following decade. Amazon lost about $1.4 billion that year; it is listed as the best-known survivor of the period." }));
    p.h(`<p>Cisco earned about $2.7 billion in the year to July 2000 and was briefly the most valuable company in the world. Its revenue is several times larger today. ${gs("CSCO")} Microsoft and Intel did not have a losing year in the decade that followed. ${gs("MSFT")} ${gs("INTC")} The lesson of these rows is narrow but firm: <b>being a money-making machine did not protect a share price that had run far ahead of the money.</b> What it protected was the company.</p>`);
    p.h('<div class="grid2">'); for (const s of ["CSCO", "MSFT", "INTC", "ORCL"]) p.fig({ type: "candle", src: site.bars(s, "dc", "1998-01-02", "2004-12-31", 420), from: "1998-06-01", to: "2004-12-31", tf: "W", log: true, h: 300, title: s, panels: [{ k: "vol", h: 44 }], marks: [{ d: e00.peak, k: "high", t: "S&P high", c: "#55534e" }, { d: e00.low, k: "low", t: "S&P low", c: "#55534e" }] }, { title: `${s} · ${nameOf(s)}, weekly, 1998–2004`, minH: 400 }); p.h("</div>");
    p.sec("today", "Today's leaders, for comparison", `Where the largest AI-era companies stand on ${nice(C.asOf)}.`);
    const todays = ["NVDA", "AVGO", "MSFT", "GOOGL", "META", "AMZN", "AAPL", "TSM", "AMD", "MU", "ORCL", "PLTR", "TSLA"];
    const rowT = sym => { const B = L.anyBars(sym); if (!B) return null; const n = B.length - 1, a = L.bia(B, "2025-11-01"); let pk = a; for (let i = a; i <= n; i++) if (B[i].c > B[pk].c) pk = i; const r = (k) => (n - k >= 0 ? (B[n].c / B[n - k].c - 1) * 100 : null), since = iso => { const k = L.bi(B, iso); return k >= 0 ? (B[n].c / B[k].c - 1) * 100 : null; };
      return [`<b>${sym}</b> <span class="dim">${nameOf(sym)}</span>`, nice(B[pk].d), PB((B[n].c / B[pk].c - 1) * 100, 60, 0), P(since("2022-10-12"), 0), P(since("2025-04-08"), 0), P(r(252), 0)]; };
    p.h(tbl(["Company", "High of the last 12 months", { t: "From that high", num: true }, { t: "Since the Oct 2022 low", num: true }, { t: "Since the Apr 2025 low", num: true }, { t: "Last 12 months", num: true }], todays.map(rowT).filter(Boolean), { note: "Split-adjusted closes." }));
    p.h('<div class="grid2">');
    p.fig({ type: "candle", src: site.bars("QQQ", "dc", "1999-03-10", "2004-06-30", 60), from: "1999-03-10", to: "2004-06-30", tf: "W", log: true, h: 320, title: "QQQ 1999-2004", panels: [{ k: "vol", h: 44 }] }, { title: "Nasdaq-100 (QQQ), weekly, 1999–2004", cap: "From its first day of trading. −83% high to low.", minH: 420 });
    p.fig({ type: "candle", src: site.bars("QQQ", "ai", "2022-01-03", C.asOf, 420), from: "2022-06-01", to: C.asOf, tf: "W", log: true, h: 320, title: "QQQ 2022-2026", panels: [{ k: "vol", h: 44 }] }, { title: "Nasdaq-100 (QQQ), weekly, 2022–2026", cap: "The AI advance from the October 2022 low to the present drop.", minH: 420 });
    p.fig({ type: "candle", src: site.bars("^SOX", "dc", "1998-01-02", "2004-06-30", 420), from: "1998-10-01", to: "2004-06-30", tf: "W", log: true, h: 320, title: "SOX 1998-2004", panels: [] }, { title: "Semiconductor index (SOX), weekly, 1998–2004", minH: 380 });
    p.fig({ type: "candle", src: site.bars("^SOX", "ai", "2022-01-03", C.asOf, 420), from: "2022-06-01", to: C.asOf, tf: "W", log: true, h: 320, title: "SOX 2022-2026", panels: [] }, { title: "Semiconductor index (SOX), weekly, 2022–2026", cap: `${pct(M.now.idx.find(x => x.sym === "^SOX").offHigh, 0)} from its June 2026 high.`, minH: 380 });
    p.h("</div>");
    p.frag("ai-vs-dotcom");
    p.frag("now-fundamentals", "ai-capex");
    p.h(take([(() => { const g = ["CSCO", "MSFT", "INTC", "ORCL", "QCOM", "TXN", "AMAT"].map(gstat); return `The argument “these companies make money, so this is not 2000” is right about the companies and does not settle the shares. Seven of the profitable leaders of 2000 (Cisco, Microsoft, Intel, Oracle, Qualcomm, Texas Instruments, Applied Materials) fell ${Math.round(-Math.max(...g.map(x => x.fall)))}% to ${Math.round(-Math.min(...g.map(x => x.fall)))}% and needed ${Math.round(Math.min(...g.map(x => x.years)))} to ${Math.round(Math.max(...g.map(x => x.years)))} years to regain their highs while their businesses kept growing.`; })(),
      `What broke in 2000–02 was a capital-spending cycle financed on the assumption of ever-rising demand, and the price that had been paid for the leaders. Whether today's spending cycle is of that kind is the open question; the research sections above give the numbers on both sides.`,
      `The differences are real too: the largest spenders fund most of their capex from operating cash flow, the Nasdaq-100's valuation at the 2026 high was well below its March 2000 multiple, and demand so far has exceeded supply. The similarities that have appeared in 2026 (debt-financed data centres, negative free cash flow at three of the largest, record IPOs, the central bank drawing the telecom comparison) are recent.`,
      `For a trader the practical content is not a forecast. It is that a 2000-type path cannot be excluded by pointing at profits, so both paths need to be held in mind (${link("scenarios")}).`], "What to take from it"));
    p.h(warn(`Share-price history of survivors only: the hundreds of 2000-era companies that vanished are not in the table, which makes 2000 look kinder than it was. The comparison of valuations and capital spending rests on the research notes, with their own caveats and unverified items marked.`));
  }

  // =============================================================== SCENARIOS
  {
    const p = site.page("scenarios");
    p.lede = "Two kinds of path lead on from a 10% fall: a correction that ends within a few months, and a bear market that takes a year or more. This page describes what each kind has looked like from this point, so that either can be recognised as it unfolds. It ranks no outcome as likely.";
    const grp = { "Corrections (ended above −20%)": done.filter(e => e.depth > -20), "Bears of 20% to 35%": done.filter(e => e.depth <= -20 && e.depth > -36 && e.daysToLow > 100), "Crashes (20%+ within 80 sessions)": done.filter(e => e.depth <= -20 && e.daysToLow <= 80), "The three long bears (1973, 2000, 2007)": done.filter(e => ["1973", "2000", "2007"].includes(e.id)) };
    const md2 = (a, f) => { const v = a.map(f).filter(x => x != null && isFinite(x)); return v.length ? median(v) : null; };
    p.sec("kinds", "The kinds of drop, in numbers", "All completed S&amp;P 500 drops of 10% or more since 1950, grouped by how they ended. Medians.");
    p.h(tbl(["", ...Object.keys(grp).map(k => ({ t: k, num: true }))], [["Number of drops", ...Object.values(grp).map(a => a.length)], ["Depth", ...Object.values(grp).map(a => P(md2(a, e => e.depth), 0))], ["Sessions from high to low", ...Object.values(grp).map(a => num(md2(a, e => e.daysToLow), 0))], ["Sessions from high to a new 52-week high", ...Object.values(grp).map(a => num(md2(a, e => e.daysToEnd), 0))], ["Rallies of 5%+ that failed", ...Object.values(grp).map(a => num(md2(a, e => e.nFailed), 0))],
      ["False reclaims of the 50-day average on the way down", ...Object.values(grp).map(a => num(md2(a, e => e.sig.false50), 0))], ["Highest VIX close (since 1990)", ...Object.values(grp).map(a => num(md2(a, e => e.sig.vixMax), 0))], ["Baa credit spread: rise from the peak, points (since 1986)", ...Object.values(grp).map(a => { const v = md2(a, e => e.sig.baaRise); return v == null ? "—" : "+" + num(v, 2); })], ["Lowest share of stocks above their 200-day (since 1999)", ...Object.values(grp).map(a => { const v = md2(a, e => e.sig.a200min); return v == null ? "—" : num(v, 0) + "%"; })],
      ["Sessions after the low to regain the 200-day", ...Object.values(grp).map(a => num(md2(a, e => e.sig.r200), 0))], ["Gain one year after the low", ...Object.values(grp).map(a => P(md2(a, e => e.sig.g250), 0))]], { note: "Groups: " + Object.entries(grp).map(([k, a]) => `${k}: ${a.map(e => e.peak.slice(0, 4)).join(", ")}`).join(". ") + "." }));
    p.sec("paths", "Two paths from here, side by side", "What the record shows for each kind of path after its first 10% fall. Observations, not instructions.");
    p.h(tbl(["", "If it is a correction (the 1998, 2011, 2015–16, 2018 kind)", "If it is a bear (the 2000, 2007, 2022 kind)"], [
      ["Time", "Low within one to four months of the high; new high within about seven months of the low", "Low 9 to 30 months after the high; years to a new high in 2000 and 2007"],
      ["Rallies", "None, one or two rallies of 5%+ fail; then one holds", `Rally after rally fails: 6 in 2022, 15 each in 2000–02 and 2007–09. Of ${done.filter(e => e.nFailed >= 2).length} drops with two or more failed rallies, ${done.filter(e => e.nFailed >= 2 && e.depth <= -20).length} went on to 20% or more`],
      ["The first big rally", "Gets back above the 50-day and 200-day averages and stays there", "Often gets above the 50-day, sometimes the 200-day, then rolls over; the 200-day average itself turns down"],
      ["Breadth", "A washout (in the deeper corrections fewer than a fifth of stocks above their 200-day average), then a broad surge within three weeks of the low", "Washouts that do not produce a surge; breadth stays weak for months; later lows come with fewer new lows than earlier ones"],
      ["VIX", "Spikes, curve inverts, peaks at or just before the low, falls away quickly", "Peaks months before the final low; grinds; several lesser spikes"],
      ["Credit", "Spreads widen up to about a point and peak near the low", "With a recession (2000–02, 2008–09): spreads widen two to four points and keep widening between equity lows. In the 2022 bear they widened only 0.6 point"],
      ["Earnings", "Estimates flat or trimmed; reported earnings keep growing or dip briefly", "Estimates fall quarter after quarter; reported earnings fall by a third to more than half"],
      ["The Fed", "Stops or eases within weeks of the low, because inflation allows it (1998, January 2019)", "Either cannot stop because of inflation (1973–74, 2022) or cuts all the way down without effect (2001, 2007–08)"],
      ["Leaders", "The leaders of the advance fall with the market and lead again afterwards", "The leaders of the advance fall most and do not lead the next one (technology after 2000, financials after 2007)"],
      ["The rest of the market", "Falls together with the leaders", "In 2000–02 the average stock and the defensive sectors rose for long stretches while the index fell; in 2008 nothing was spared"],
      ["News", "Good news is sold until the low; then bad news stops making new lows", "Good news is sold for a year or more; “bad news bought” days occur at every failed rally"]], { cls: "wrap" }));
    p.frag("scenarios-table");
    p.sec("today", "Which features of each path are present today", `A tally as of ${nice(C.asOf)}, ${N} sessions in. Each line cites the page with the evidence.`);
    const n = M.now, X = M.leaders[cur.id], mk = M.macro[cur.id].peak;
    p.h(tbl(["Feature", "Reading today", "Path it is typical of"], [
      ["Age and depth", `${N} sessions, ${pct(cur.depth)}`, "either; base rate about even between “nearly over” and “half-way or less”"], ["Failed rallies of 5%+ so far", String(cur.rallies.filter(r => r.cls === "failed").length), "either (corrections had none to two)"],
      ["Index against its 200-day average", pct(n.idx[0].vs200) + ", first closes below it this week", "either; what the average's slope does over the next months separates them"], ["Breadth washout", `${num(n.breadth.a200, 0)}% of stocks above their 200-day average`, "not at the level seen at the low of any drop of 18% or more since 1999 (under 21%)"],
      ["What is falling", `leaders ${pct(X.qB252[4].dec, 0)}, median stock ${pct(X.medDec, 0)}, ${num(X.rose, 0)}% of stocks up`, "the 2000 kind of beginning; unlike 2018"], ["VIX and its curve", `${num(n.vix.c, 0)} at the last close in the data; curve ${n.vix.ratio > 1 ? "inverted" : "not inverted"}`, "either"],
      ["Credit spreads", `Baa spread up ${num(cur.sig.baaRise, 2)} point from the peak`, "calm: less widening than at the same stage of 2018, 2000, 2007 or 2022"], ["Earnings", "growing about a third; estimates still rising (FactSet, via the research notes)", "the correction kind so far; also true of the first months of 2000"],
      ["Inflation and the Fed", `${num(mk.cpi, 1)}% and rising at the peak; the Fed raising rates`, "leaves less room for the 1998 / 2019 kind of ending; resembles 2022 and 1999–2000"], ["Valuation at the peak", `Shiller P/E ${num(mk.cape, 0)}`, "the 2000 kind"], ["Margin loans", `up ${pct(mk.marginYoy, 0)} in a year to ${num(mk.marginPctGdp, 2)}% of GDP at the peak`, `between 2018 (${pct(M.macro["2018b"].peak.marginYoy, 0)}, ${num(M.macro["2018b"].peak.marginPctGdp, 2)}%) and 2000 (${pct(M.macro["2000"].peak.marginYoy, 0)}, ${num(M.macro["2000"].peak.marginPctGdp, 2)}%)`],
      ["Time of day", "all of the loss in regular hours", "the 2018 kind"]], { cls: "wrap" }));
    p.frag("signals-seasonality");
    p.sec("watch", "What would tell the two apart from here", "The markers below are the ones that differed most between the two kinds of path in the record. They are things to observe, in rough order of when they appeared.");
    p.h(ul([`<b>Whether the first real rally holds.</b> In corrections the first or second rally of 5%+ was the low. Of the drops with two or more failed rallies, ${done.filter(e => e.nFailed >= 2 && e.depth <= -20).length} of ${done.filter(e => e.nFailed >= 2).length} went to 20% or more, against ${done.filter(e => e.depth <= -20).length} of ${done.length} overall (${link("bounces", "count", "count")}).`,
      `<b>Whether a washout is followed by a broad surge.</b> The lows of every drop of 18% or more since 1999 came with fewer than 21% of stocks above their 200-day average, and most real turns were followed within three weeks by a breadth thrust (${link("bottoms", "breadth", "breadth")}).`,
      `<b>Whether the former leaders stop making relative lows.</b> In 2018 semiconductors and software stopped underperforming one to two months before the index low and led afterwards; in 2000–02 technology made relative lows to the end (${link("sectors")}).`,
      `<b>Whether the average stock joins the fall.</b> So far it has not. In 2000–02 it never fully did; in 2008 it did, completely.`, `<b>Whether credit spreads widen past about one point.</b> They widened 1.8 to 4.3 points in 2000–02, 2008–09 and 2020 and 1.1 or less in every other drop since 1987, the 2022 bear included (${link("bottoms", "credit", "credit")}).`,
      `<b>Whether earnings estimates start to fall.</b> They are rising now. In 2000 they peaked about six months after the index.`, `<b>Whether inflation gives the Fed room.</b> The 1998 and 2018 drops ended with a Fed that could stop. In 2022 it could not, and the drop lasted until inflation turned.`,
      `<b>What the 200-day average's slope does.</b> It was still rising at every correction low and had been falling for months at every bear low.`]));
    p.h(warn(`The two columns are built from a handful of episodes each, sorted by an outcome known only afterwards. Real drops mix features of both: 2022 had a correction's breadth and a bear's length; 1987 had a crash's depth and a correction's economy. The tally of today's readings is a description, not a score to be added up.`));
  }

  // =============================================================== DRILLS
  {
    const p = site.page("drills"), B = L.bars("^GSPC").filter(b => b.d >= "1949-01-01"), rnd = L.rng(20261120);
    p.lede = "Thirty unlabeled charts. Each stops five sessions after a closing low inside a real S&amp;P 500 drop: a pop is under way. Decide whether the low will hold, then step forward a day, a week or a month at a time, or reveal the rest.";
    p.h(`<p>The charts are daily candles of the S&amp;P 500 with volume, the 9- and 20-day EMA and the 50- and 200-day SMA, as on the other pages. Dates are hidden and prices are rebased so that the last visible close is 100; the axis counts sessions from that day. About half of the thirty lows held and half failed, in random order. Nothing is scored: the point is to notice what the eye is drawn to and how often it is right.</p>
<p>Before revealing, it helps to say out loud: how far below the 200-day average is this? Is this the first low of the drop or a later one? What did volume do? Would a close above the 50-day change the view? Then compare with the base rates on ${link("bounces")}: across 76 years the first five days of the rallies that held and of those that failed were nearly indistinguishable.</p>`);
    const pool = done.filter(e => e.peak >= "1962").flatMap(e => e.rallies.filter(r => r.cls === "turn" || r.cls === "failed").map(r => ({ r, e }))).filter(x => x.r.lowI + 66 < B.length && x.r.lowI > 330);
    const turns = pool.filter(x => x.r.turn), fails = pool.filter(x => !x.r.turn); const pick = (a, k) => { const c = a.slice(), out = []; while (out.length < k && c.length) out.push(c.splice(Math.floor(rnd() * c.length), 1)[0]); return out; };
    const set = pick(turns, 15).concat(pick(fails, 15)); for (let i = set.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [set[i], set[j]] = [set[j], set[i]]; }
    set.forEach((x, k) => { const { r, e } = x, cut = r.lowI + 5, a = cut - 320, z = cut + 60, base = B[cut].c / 100, sl = B.slice(a, z + 1), f4 = v => +(v / base).toFixed(2), vb = Math.max(...sl.map(b => b.v)) || 1;
      const g60 = (B[cut + 60].c / B[cut].c - 1) * 100, ans = r.turn ? `<b>It held.</b> This was the low of ${nice(r.low)}, the final low of the ${label(e)} drop (${pct(e.depth)} from the ${nice(e.peak)} high). Sixty sessions after the chart stopped the index was ${pct(g60)}.`
        : `<b>It failed.</b> This was the low of ${nice(r.low)} in the ${label(e)} drop, ${pct(r.depthAtLow)} below the ${nice(e.peak)} high at the time. The rally reached ${pct(r.gain)} after ${r.days} sessions; the low was broken ${r.daysToCut} sessions after it was made. The drop ended on ${nice(e.low)} at ${pct(e.depth)}.`;
      p.fig({ type: "candle", anon: true, data: { e: sl.map((_, i) => i), o: sl.map(b => f4(b.o)), h: sl.map(b => f4(b.h)), l: sl.map(b => f4(b.l)), c: sl.map(b => f4(b.c)), v: sl.map(b => Math.round(b.v / vb * 1000)) }, i0: 200, i1: 380, h: 380, reveal: { cutI: 320, steps: [1, 5, 20], answer: ans }, title: "Drill " + (k + 1) }, { title: `Drill ${k + 1}`, cap: "Does this low hold?", minH: 520 }); });
    p.h(warn(`Thirty cases drawn from drops since 1962; the same thirty every time the page is built from the same data. Knowing that half held is itself a clue a trader never has. The drill trains recognition of what a low looks like on the fifth day; it cannot supply the context (the Fed, earnings, breadth) that the other pages show mattered more.`));
  }

  // =============================================================== GLOSSARY
  {
    const p = site.page("glossary");
    p.lede = "The terms used on these pages, in plain words.";
    const T = [["Advance / decline", "The number of stocks that rose on a day against the number that fell. “Share of advancers” here = rising stocks ÷ (rising + falling), in this study's universe of about 660 large stocks."],
      ["Base rate", "How often something happened across all past cases, before looking at the details of the present one."], ["Bear market", "By convention a fall of 20% or more in an index from its high. On these pages, “the long bears” means 1973–74, 2000–02 and 2007–09."],
      ["Breadth", "How many stocks take part in a move. Measured here by the share of stocks above their 50-day or 200-day average, at 52-week lows, or advancing on the day."], ["Breadth thrust", "A sudden, broad surge in the share of rising stocks after a decline. Several named definitions exist (Zweig, Whaley, Deemer); this study uses its own stand-ins computed on its stock universe."],
      ["CAPE (Shiller P/E)", "Index price divided by the average of the last ten years of inflation-adjusted earnings. A slow valuation gauge."], ["Capitulation", "A burst of forced or panicked selling, usually on very high volume with nearly all stocks falling."], ["Close location", "Where the close sits in the day's range: 0 at the low, 1 at the high."],
      ["Correction", "By convention a fall of 10% to 20% from a high."], ["Credit spread", "The extra yield investors demand to hold corporate bonds rather than Treasuries. It widens when lenders fear defaults. The Baa spread used here is Moody's Baa corporate yield minus the 10-year Treasury yield."],
      ["Death cross / golden cross", "The 50-day average crossing below / above the 200-day average."], ["Drop", "On these pages: the index closes at least 10% below its highest close of the past 252 sessions. It runs from that high (the peak) to the lowest close before a new 52-week high (the low)."],
      ["EMA / SMA", "Exponential and simple moving averages. The charts show the 9- and 20-day EMA and the 50- and 200-day SMA; weekly charts show 10- and 40-week SMAs."], ["Equal-weight index", "An index in which every stock counts the same, so it shows what the average stock is doing. RSP is the equal-weight S&amp;P 500 fund."],
      ["Failed rally", "A rise of 5% or more from a closing low inside a drop, whose starting low is later broken on a closing basis."], ["Fed pivot", "A change in the Federal Reserve's direction or stated intention, from tightening to pausing or easing."], ["Follow-through day", "From the fourth to about the fifteenth session of an attempted rally, a gain of 1.25% or more in the index on higher volume than the day before, without the low having been broken. A term from William O'Neil and Investor's Business Daily."],
      ["Forward P/E", "Index price divided by analysts' expected earnings for the next twelve months."], ["Gap", "The difference between today's open and yesterday's close. A gap up is “sold” if the day closes below its open."], ["Margin debt", "Money borrowed from brokers against securities. Reported monthly by FINRA and quarterly in the Fed's accounts."],
      ["Momentum crash", "The pattern, documented by Daniel and Moskowitz, that at market lows the stocks that fell most rebound far more than the stocks that held up."], ["90% day", "A day on which 90% or more of volume was in rising stocks (up day) or falling stocks (down day)."], ["Overnight / session", "Overnight = previous close to today's open. Session = today's open to today's close."],
      ["Policy rate", "The Federal Reserve's target for the overnight federal funds rate (the middle of the target range since 2008)."], ["Relative strength line", "A stock's or sector's price divided by the index's. Rising = outperforming. Its low inside a drop is the day the group stopped underperforming."], ["Retest", "After a low and a first rally, a fall back to near the low. Here: a close within 3% of the low between 5 and 60 sessions after it."],
      ["Session", "One trading day. About 21 sessions make a month and 252 a year."], ["Survivorship bias", "The distortion from studying only companies that still exist: the ones that failed are missing, so the past looks better than it was."], ["The turn", "The rally that starts at the final low of a drop."],
      ["V-bottom / W-bottom", "A low followed by an uninterrupted recovery (V), or by a rally, a retest near the low and then a recovery (W)."], ["VIX", "The options market's estimate of S&amp;P 500 volatility over the next 30 days, as an annualised percentage. The 3-month VIX is the same for the next three months; when VIX is above it, the curve is “inverted”."],
      ["Yield curve", "The difference between long-term and short-term Treasury yields (here 10-year minus 2-year, or minus 3-month). Negative = inverted."]];
    p.h(`<dl class="gl">${T.sort((a, b) => a[0].localeCompare(b[0])).map(([t, d]) => `<dt id="${t.toLowerCase().replace(/[^a-z0-9]+/g, "-")}">${t}</dt><dd>${d}</dd>`).join("")}</dl><style>.gl dt{font-weight:700;margin-top:14px}.gl dd{margin:2px 0 0 0;color:#2b2a27}</style>`);
  }

  // =============================================================== METHOD
  {
    const p = site.page("method"), cov = L.J("coverage.json"), U = L.universe();
    p.lede = "How the study was built: the definitions, the data and its coverage, what was computed, and the limits that apply to every page.";
    p.sec("defs", "Definitions", "");
    p.h(ul([`<b>Drop.</b> The S&amp;P 500 closes 10% or more below its highest close of the previous 252 sessions. Peak = that high. Low = the lowest close before the next new 52-week closing high, which ends the drop. ${E.length} since 1950.`, `<b>Rally, failed rally, the turn.</b> Inside a drop, closes are cut into swings by a 5% reversal rule. A rally is a rise of 5%+ from a swing low; it failed if a later close in the same drop went below that low; the rally from the final low is the turn.`,
      `<b>Sessions.</b> Trading days. “After the low” counts from the close of the low day.`, `<b>Stock universe.</b> ${Object.values(U.stocks).filter(s => s.sp500).length} members of today's S&amp;P 500, the Nasdaq-100, and a hand list of past and present leaders that still trade: ${cov.stocks ? cov.stocks.n : "about 660"} stocks with daily bars from 1998 or their listing. Breadth = shares of this universe.`,
      `<b>Returns.</b> Index levels are price only. ETF and stock returns use closes adjusted for splits and dividends. Charts show split-adjusted prices.`, `<b>Fed stance.</b> “Hiking” / “cutting” = the policy rate moved by a quarter point or more over the previous six months (before 1983: half a point in the effective rate).`,
      `<b>Follow-through day.</b> Sessions 4 to 15 after a swing low, index up 1.25%+ on higher volume than the previous day, low not broken first.`, `<b>Hand-kept breadth gauges.</b> Share of the universe closing above its own 10-day EMA, 20-day EMA and 50-day average; share closing 4% or more above or below the previous close; the 10-day ratio of the two; share 25% or more below the close of 65 sessions earlier. Tested on ${link("gauges")}.`, `<b>Breadth-thrust stand-ins.</b> A: best 10-session average share of advancers within 20 sessions ≥ 61.5%. B: ≥ 55% of stocks at a 20-day closing high on one day within 20 sessions. C: ≥ 90% of stocks above their 50-day average within 40 sessions.`]));
    p.sec("data", "Data and coverage", "Everything is free public data, downloaded " + nice((cov.fetchedAt || C.asOf).slice(0, 10)) + ".");
    const rows = Object.entries(cov.series).map(([k, v]) => [k.replace(/^(Yahoo|FRED|CBOE):/, ""), v.what || "", v.source || k.split(":")[0], v.from || "", v.to || ""]);
    p.h(`<details><summary>Every series, with its first and last date (${rows.length})</summary>${tbl(["Series", "What it is", "Source", "From", "To"], rows, { cls: "small wrap" })}</details>`);
    p.h(ul([`<b>Prices:</b> Yahoo Finance daily bars. S&amp;P 500 from 1950 (open, high and low are reliable from 1962), Nasdaq Composite from 1971, sector funds from December 1998, industry funds from their listing.`, `<b>Volatility:</b> CBOE's VIX history (1990), 3-month VIX (2006), VVIX (2007); the old put/call archive ends in October 2019.`,
      `<b>Macro:</b> FRED (Federal Reserve Bank of St. Louis): policy rate, Treasury yields, CPI, unemployment, jobless claims, Baa spread, oil, dollar, Fed balance sheet, the Fed's quarterly margin-loan series, GDP. The high-yield spread on FRED covers only the last three years and is not used.`, `<b>Industries before 1999:</b> Ken French's data library (12 and 49 industry portfolios, daily from 1926).`, `<b>Valuation and earnings:</b> Shiller's CAPE and trailing S&amp;P earnings via multpl.com.`,
      `<b>Intraday:</b> 30-minute bars of SPY and QQQ for the last two years (Polygon). No intraday data before that.`, `<b>Not available free, taken from the research notes instead:</b> forward earnings and P/E (FactSet), FINRA monthly margin debt, hedge-fund leverage, NYSE advance/decline and new-low counts, fund flows, sentiment surveys.`]));
    p.sec("research", "Research", `Four research passes (2018; the 2000–02 and 2007–09 bears and the AI comparison; other drops and the evidence on bottoming signals; the present) collected dated facts with sources. Their notes are on ${link("sources")}. The narrative sections on the pages are written from those notes; anything that could not be re-checked is marked <span class="unv">not verified</span>.`);
    p.sec("limits", "Limits that apply everywhere", "");
    p.h(ul([`<b>Small samples.</b> ${E.length} drops since 1950; 13 since 1999 with stock-level breadth; three long bears. Medians of small groups move a lot when one case is added.`, `<b>Hindsight.</b> A “low” is known only afterwards. Every table of what surrounded lows is a description of the past, not a rule that could have been followed.`,
      `<b>Survivorship.</b> The stock universe is today's membership. For 2000–02 and 2007–09 the companies that failed are missing; breadth and leader tables for those years are flattering.`, `<b>One market, closing prices.</b> US large caps, daily closes. Intraday extremes, other markets and smaller stocks can differ.`,
      `<b>No strategy is tested.</b> No entries, exits, costs, slippage or position sizing. A share that “would have” been captured is not claimed anywhere.`, `<b>An unfinished event.</b> Everything about 2026 describes a drop still running on ${nice(C.asOf)}.`, `<b>Not advice.</b> The study describes; it does not recommend.`]));
    p.sec("rebuild", "Rebuilding", "The code is in <code>scripts/marketdrops/</code> of the repository. One command downloads the data, recomputes everything and rebuilds these pages: <code>node scripts/marketdrops/run.js</code>.");
  }

  // =============================================================== SOURCES
  {
    const p = site.page("sources"), dir = path.join(__dirname, "research");
    p.lede = "The research notes behind the narrative sections, as the researchers wrote them: dated facts, tables, and every source with its link. Raw material, kept for checking.";
    p.h(warn(`These are working notes, not polished text. Items the researchers could not verify are flagged inside each note. Where a note and a page disagree on a price or breadth figure, the page uses the figure computed from daily data.`, "How to use these"));
    for (const [f, t] of [["now-2026.md", "The present: June to 20 November 2026"], ["2018.md", "2018: both drops and the recovery"], ["bears-2000-2007.md", "The 2000–02 and 2007–09 bears, and the AI comparison"], ["other-drops-and-signals.md", "Other drops and the evidence on bottoming signals"], ["breadth-gauges.md", "The hand-kept breadth gauges: origins, thresholds, published tests"]]) {
      const file = path.join(dir, f); if (!fs.existsSync(file)) { site.missing.push("research " + f); continue; } const txt = fs.readFileSync(file, "utf8");
      p.sec(f.replace(/\W+/g, "-"), t, `${Math.round(txt.split(/\s+/).length / 100) * 100} words.`); p.h(`<details><summary>Open the note</summary><div class="note">${md(txt)}</div></details>`); }
    p.h("<style>.note h3{font-size:19px;margin-top:26px}.note h4{font-size:16.5px}.note h5{font-size:15px}.note{font-size:14.5px}.note a{word-break:break-all}</style>");
  }

  // =============================================================== INDEX
  {
    const p = site.page("index"), n = M.now, X = M.leaders, cr = C.cross10.filter(r => !r.open), A = C.analog, x18 = A.cand.findIndex(x => x.peak === e18.peak) + 1, RL = done.flatMap(e => e.rallies), failed = RL.filter(r => r.cls === "failed"), turn = RL.filter(r => r.cls === "turn");
    const sh18 = M.shape["2018b"].SPY, shN = M.shape[cur.id].SPY, mk = M.macro[cur.id].peak, mk18 = M.macro["2018b"].peak, lev = M.lev[M.lev.length - 1];
    p.title = "Anatomy of a Drop"; p.lede = `A study of how US stock-market drops unfold and end, built around one question: how far does the autumn of 2026 resemble the autumn of 2018, and what would it look like if it turned out more like 2000 or 2007 instead? ${E.length} drops since 1950, measured the same way, with the charts to train the eye on.`;
    p.h(`<p>The study has ${G.ORDER.length} pages. Each can be read alone; repetition between them is deliberate. Charts are interactive: hover or tap for dates and prices; wide charts scroll sideways on a phone. Candles are white for up days and black for down days, with the 9- and 20-day EMA and the 50- and 200-day SMA. This is a historical study and not advice: it describes what happened and how often, and nothing in it says what to buy or sell.</p>`);
    p.h(tiles([[pct(cur.depth), `S&amp;P 500 from its ${niceS(cur.peak)} high, ${N} sessions in`, "neg"], [`${cr.filter(r => r.finalDepth <= -20).length} of ${cr.length}`, "earlier 10% drops that went on to 20% or more"], [`${x18} of ${A.cand.length}`, "rank of 2018 as a chart match for the present, measured from the peak"], [pct(X[cur.id].medDec), "the median large stock since the index high (2018: " + pct(X["2018b"].medDec, 0) + " by the low)"], [`${failed.length} : ${turn.length}`, "rallies of 5%+ inside drops that failed, against those that were the low"], [num(n.breadth.a200, 0) + "%", "of stocks above their 200-day average (under 21% at the low of every drop of 18%+ since 1999)"]]));
    p.sec("findings", "The main findings", "Each links to the page with the evidence.");
    p.h(`<ol class="find">${[
      [`<b>A 10% fall is a fork, not a verdict.</b> Of ${cr.length} earlier drops that reached −10%, ${cr.filter(r => r.finalDepth > -15).length} ended before −15% and ${cr.filter(r => r.finalDepth <= -20).length} went to −20% or more. A year after the first −10% close the index was higher ${cr.filter(r => r.f252 > 0).length} times.`, "atlas"],
      [`<b>The look-alike chart is weak evidence.</b> Measured from the peak, 2018 ranks ${x18} of ${A.cand.length} as a match for the present path. Across ${A.loo.length} past declines, the closest-matching charts had no forecasting value for the next 60 sessions (correlation ${A.looCorr.toFixed(2)}).`, "lookalike"],
      [`<b>On the macro numbers the comparison with 2018 has a basis.</b> The backdrop at the October 2026 high was closest to ${niceM(ep(M.macroSim[0].id).peak)} among all peaks since 1987: a hiking Fed, low unemployment, calm credit, strong earnings. March 2000 ranks ${["first", "second", "third", "fourth", "fifth", "sixth"][M.macroSim.findIndex(x => x.id === "2000")] || "lower"}.`, "fundamentals"],
      [`<b>What is falling is unlike 2018.</b> In 2018 the median stock fell ${mag(X["2018b"].medDec, 0)} with the index and no sector rose. Now the median stock is ${pct(X[cur.id].medDec, 0)}, ${num(X[cur.id].rose, 0)}% of stocks are up, staples and health care have risen, and the previous leaders are down ${mag(X[cur.id].qB252[4].dec, 0)}. That shape is how 2000 began.`, "compare"],
      [`<b>Three things that ended 2018 are missing or weaker.</b> Inflation was 2% and falling, so the Fed could stop within two weeks of the low; now it is ${num(mk.cpi, 1)}% and rising. The valuation reset to its long-run average; it started far higher this time (Shiller P/E ${num(mk.cape, 0)} against ${num(mk18.cape, 0)}). Margin loans had grown ${pct(mk18.marginYoy, 0)} in a year to ${num(mk18.marginPctGdp, 2)}% of GDP; this time ${pct(mk.marginYoy, 0)} to ${num(mk.marginPctGdp, 2)}%.`, "compare"],
      [`<b>Profits do not settle it.</b> Cisco, Microsoft, Intel and Oracle were highly profitable in 2000; their shares fell 65% to 89% and took 17 to 26 years to regain their highs. Being a money-making machine protected the company, not the share price.`, "ai-dotcom"],
      [`<b>A pop is not a low.</b> In their first five sessions the ${turn.length} real lows and the ${failed.length} failed rallies were nearly identical in size, volume and number of up days. A pop alone was the low about ${Math.round(turn.length / (turn.length + failed.length) * 100)}% of the time.`, "bounces"],
      [`<b>What separated real turns was breadth and persistence.</b> A follow-through day came after ${Math.round(failed.filter(r => r.f.ftd != null).length / failed.length * 100)}% of failed rallies as well. A broad breadth surge within three weeks came after most real lows and few failed ones. ${Math.round(failed.filter(r => r.f.r50ok).length / failed.length * 100)}% of failed rallies got back above the 50-day average.`, "bounces"],
      [`<b>Proof costs part of the move.</b> At real lows the index was back above its 50-day average after a median ${median(done.map(e => e.sig.r50).filter(x => x != null))} sessions and ${pct(median(done.map(e => e.sig.r50gain).filter(x => x != null)), 0)} off the low, and above its 200-day after ${median(done.map(e => e.sig.r200).filter(x => x != null))} sessions and ${pct(median(done.map(e => e.sig.r200gain).filter(x => x != null)), 0)} (17% to 39% in the V-shaped lows of 2018, 2020 and 2009).`, "filters"],
      [`<b>December 2018 gave no second chance.</b> The low came on a quiet half-day; the next session rose 5%; there was no retest; the stages of proof arrived over three weeks. It is one of very few clean V-bottoms in 76 years.`, "y2018-turn"],
      [`<b>Signs at lows: washout first, proof after.</b> VIX peaked at the low in fast drops and months before it in slow ones. Volume on the low day meant little. At the low of every drop of 18% or more since 1999 fewer than 21% of stocks were above their 200-day average; today it is ${num(n.breadth.a200, 0)}%.`, "bottoms"],
      [`<b>The fall has come in regular hours, as in 2018.</b> From its high to its low in 2018 SPY gained ${pct(sh18.fall.overnight)} overnight and lost ${mag(sh18.fall.session)} between open and close; ${num(sh18.fall.gapUpSold, 0)}% of gap-ups were sold. So far in 2026: overnight ${pct(shN.fall.overnight)}, session ${pct(shN.fall.session)}. After the 2018 low the pattern flipped within days.`, "intraday"],
      [`<b>Shelters lag afterwards; early relative strength leads.</b> Staples, utilities and health care were among the smallest fallers in nearly every drop and trailed for six months after almost every low. In 2018 the relative-strength lines of semiconductors, homebuilders and software bottomed one to two months before the index and those groups led in 2019.`, "sectors"],
      [`<b>Who leads after depends on the kind of drop.</b> In the first month off a low the hardest-hit stocks bounced most, almost every time. After 2018, 2020 and 2025 the leaders from before the drop led again. After 2000–02 they did not.`, "leaders"],
      [(() => { const Zg = L.J("gauges.json"), w = Zg.wash.find(x => x.k === "a50" && x.th === 10), c = Zg.tests.find(x => x.name.includes("50-day share ≤15%")), u = Zg.thrust.find(x => x.name.startsWith("A day with 35%")); return `<b>Hand-kept breadth gauges: good at marking the zone, poor at timing.</b> Fewer than 10% of stocks above their 50-day average happened only inside drops and was followed by a higher S&amp;P 500 60 sessions later ${w.f60.up}% of the time, but ${w.inFall} of ${w.n} such readings came before the final low. Big 4%-up days were as common in bear rallies as at lows. A washout followed by a broad surge was the best reading found (${c.precision}% were final lows against a base rate of ${c.base}%). Today the short gauges are washed out and the 50-day share is not.`; })(), "gauges"],
      [`<b>Leverage was higher going in than in 2018.</b> Brokers' margin loans stood at ${num(lev.pctGdp, 2)}% of GDP (${(d => `Q${Math.floor((+d.slice(5, 7) - 1) / 3) + 1} ${d.slice(0, 4)}`)(lev.d)}), up ${pct(lev.yoy, 0)} in a year; at the 2018 high they were ${num(M.macro["2018b"].peak.marginPctGdp, 2)}%, up ${pct(M.macro["2018b"].peak.marginYoy, 0)}. The Fed reports hedge-fund leverage at its highest since its data began.`, "leverage"]]
      .map(([t, s]) => `<li>${t} <a href="${s}.html">${G.TITLE[s]} →</a></li>`).join("")}</ol><style>.find li{margin:10px 0}.find a{white-space:nowrap;font-size:14px}</style>`);
    p.sec("order", "A reading order", "About a week of sittings. Each page has a “studied” tick at the bottom that this browser remembers.");
    const card = (slug, note) => `<a class="card" href="${slug}.html"><b>${G.TITLE[slug]}</b><span>${note}</span></a>`;
    p.h(`<h3>Sitting 1: where things stand</h3><div class="cards">${card("now", "The drop so far: the chart with its key days, what is falling, what is not.")}${card("compare", "Autumn 2026 against autumn 2018, measure by measure, with 2000 and 2007 alongside.")}${card("atlas", "All 36 drops since 1950 and what followed a first 10% fall.")}</div>
<h3>Sitting 2: 2018 in full</h3><div class="cards">${card("y2018", "The story from the January blow-off to the April 2019 high.")}${card("y2018-turn", "The low of 24 December taken apart: what could be seen on which day.")}</div>
<h3>Sitting 3: the other path</h3><div class="cards">${card("bears", "2000–02 and 2007–09: how they began, the rallies that failed, how they ended.")}${card("ai-dotcom", "What happened to the profitable leaders of 2000; AI spending and its financing.")}${card("scenarios", "The two paths side by side, and which features of each are present today.")}</div>
<h3>Sitting 4: the turn</h3><div class="cards">${card("bounces", `${failed.length} failed rallies against ${turn.length} real lows: what looked the same and what differed.`)}${card("bottoms", "VIX, volume, breadth, credit and the Fed around every low since 1987.")}${card("gauges", "Stocks above their 10-, 20- and 50-day averages and 4% days: what they were worth.")}${card("filters", "What staying under a moving average cost and saved.")}${card("news", "Good news sold, bad news bought: how much it was worth.")}</div>
<h3>Sitting 5: what leads</h3><div class="cards">${card("sectors", "Which groups fell most, held, turned first and led, drop by drop.")}${card("leaders", "The stocks that led after each low and what they looked like on the way down. Chart gallery.")}</div>
<h3>Sitting 6: under the surface</h3><div class="cards">${card("intraday", "Overnight against session, gaps, closes, and the day by half-hours.")}${card("leverage", "Margin debt, hedge funds, leveraged funds: then and now.")}${card("fundamentals", "The macro backdrop at every peak since 1987 and a similarity score.")}${card("lookalike", "A test of whether matching charts forecast anything.")}</div>
<h3>Sitting 7: practice</h3><div class="cards">${card("drills", "Thirty unlabeled charts stopped five days after a low. Does it hold?")}${card("glossary", "Every term in plain words.")}${card("method", "Definitions, data coverage and the limits of all of it.")}${card("sources", "The research notes with every source link.")}</div>`);
    p.sec("eye", "Charts to train the eye on", "If time is short, these are the ones to return to.");
    p.h(ul([`${link("y2018-turn", "The December 2018 low, close up", "zoom")}: a quiet low, a 5% day, then weeks of closes near the highs.`, `${link("bounces", "The 2018, 2022, 2015–16 and 2011 drops with failed rallies shaded", "charts")}: what a failed pop looked like next to the one that held.`, `${link("bears", "The weekly charts of 2000–02 and 2007–09", "b2000")}: fifteen failed rallies each, several of 15% or more.`,
      `${link("leaders", "Twelve leaders of 2019 through the 2018 drop, with relative-strength lines", "y2018")}, and the four old leaders that broke.`, `${link("sectors", "Sector lines for each drop", "d2018b")}: watch which lines turn up before the black one.`, `${link("intraday", "Overnight against session", "night-day")}: the 2018 picture and the present one.`, `${link("ai-dotcom", "Cisco, Microsoft, Intel and Oracle, 1998–2004", "giants")}.`, `${link("drills")}: after the reading, not before.`]));
    p.h(warn(`Everything about 2026 describes an unfinished event as of ${nice(C.asOf)}. The study gives base rates, comparisons and descriptions. It cannot say which path the present drop will take, and no page should be read as saying so.`, "Before reading on"));
  }
};
